package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type DiscRec struct {
	DrItem  string
	DrPrice decimal.Decimal
	DrPct   int64
}

var WsEofFlag string = "N"
var WsDiscount decimal.Decimal = decimal.NewFromInt(0)
var WsNet decimal.Decimal = decimal.NewFromInt(0)
var WsTotalNet decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsPriceEd string
var WsDiscEd string
var WsNetEd string
var WsTotalEd string

var DiscRecVar DiscRec

var discFileScanner *bufio.Scanner
var discFile *os.File

func truncateDecimal(d decimal.Decimal, scale int32) decimal.Decimal {
	return d.Truncate(scale)
}

func roundDecimal(d decimal.Decimal, scale int32) decimal.Decimal {
	return d.Round(scale)
}

func storePic95V99(d decimal.Decimal) decimal.Decimal {
	d = truncateDecimal(d, 2)
	// overflow: keep low-order 7 digits (5+2) of unscaled value
	// 9(5)V99 => integer digits 5, scale 2
	// Represent as integer = d *100
	unscaled := d.Shift(2) // move decimal point right 2
	// unscaled should be integer
	// modulo 10^7
	mod := decimal.NewFromInt(1)
	for i := 0; i < 7; i++ {
		mod = mod.Mul(decimal.NewFromInt(10))
	}
	// handle negative? COBOL would keep sign; but assume non-negative here
	// For negative, need to keep sign after truncation
	neg := unscaled.Sign() < 0
	if neg {
		unscaled = unscaled.Abs()
	}
	// keep low-order digits
	// unscaled % mod
	unscaled = unscaled.Mod(mod)
	if neg {
		unscaled = unscaled.Neg()
	}
	return unscaled.Shift(-2)
}

func storePic98V99(d decimal.Decimal) decimal.Decimal {
	d = truncateDecimal(d, 2)
	mod := decimal.NewFromInt(1)
	for i := 0; i < 10; i++ {
		mod = mod.Mul(decimal.NewFromInt(10))
	}
	neg := d.Sign() < 0
	unscaled := d.Shift(2)
	if neg {
		unscaled = unscaled.Abs()
	}
	unscaled = unscaled.Mod(mod)
	if neg {
		unscaled = unscaled.Neg()
	}
	return unscaled.Shift(-2)
}

func formatEdited(value decimal.Decimal, picture string) string {
	// picture like "ZZ,ZZ9.99" or "ZZ,ZZZ,ZZ9.99"
	// Determine integer part width, scale, comma positions
	// Count digits placeholders before decimal
	dotIdx := strings.Index(picture, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		fracPic = picture[dotIdx+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	scale := len(fracPic) // number of 9/Z after dot (here always 2)
	// Truncate/round assumed already done; just format to scale
	// Need integer digits of value
	// value is decimal with scale 2
	// Get absolute value for formatting? COBOL would have sign separate; assume positive
	neg := value.Sign() < 0
	if neg {
		value = value.Abs()
	}
	// Ensure scale
	value = value.Truncate(int32(scale))
	// Get integer part and fractional part
	// integer part = floor(|value|)
	intPart := value.Truncate(0)
	fracPart := value.Sub(intPart).Abs()

	// Build integer digits string with possible overflow truncation
	// Number of digit slots in intPic = count of Z and 9
	intSlots := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intSlots++
		}
	}
	// Get integer digits as string without sign, zero padded? Actually we need lowest intSlots digits
	intStrRaw := intPart.StringFixed(0) // no decimal
	// intStrRaw is like "0", "1234" etc.
	// If intStrRaw length > intSlots, drop high-order digits
	if len(intStrRaw) > intSlots {
		intStrRaw = intStrRaw[len(intStrRaw)-intSlots:]
	}
	// left pad with zeros to intSlots
	if len(intStrRaw) < intSlots {
		intStrRaw = strings.Repeat("0", intSlots-len(intStrRaw)) + intStrRaw
	}
	// Now map to picture positions
	// intPic contains commas and Z/9
	// Build result chars
	resInt := make([]byte, len(intPic))
	slotIdx := 0
	for i := 0; i < len(intPic); i++ {
		ch := intPic[i]
		if ch == 'Z' || ch == '9' {
			resInt[i] = intStrRaw[slotIdx]
			slotIdx++
		} else {
			resInt[i] = ch // comma
		}
	}
	// Apply Z suppression: leading zeros become spaces
	// Find last Z occurrence? Actually suppression zone is from start until last Z before a 9
	// For ZZ,ZZ9 pattern, Z's are suppressed
	// Algorithm: iterate over intPic left to right; if char is Z and its digit is '0' and we are still in suppression zone (no non-zero encountered yet, and no '9' encountered), replace with space.
	// Also commas inside suppressed zone become spaces.
	suppressing := true
	for i := 0; i < len(intPic); i++ {
		pch := intPic[i]
		if pch == ',' {
			// comma is suppressed if still suppressing and all remaining? Actually COBOL: comma inside suppressed zone becomes space
			// We'll handle after digit suppression check
			continue
		}
		if pch == 'Z' {
			if suppressing && resInt[i] == '0' {
				resInt[i] = ' '
			} else {
				suppressing = false
			}
		} else if pch == '9' {
			// 9 always prints, ends suppression
			suppressing = false
		}
	}
	// Now handle commas: if comma has only spaces to its left (ignoring other commas) up to start, it becomes space; also if it's in suppressed area
	// Simpler: if suppressing was still true at comma position? Need to check
	// Re-evaluate commas: a comma becomes space if all digit positions to its left are spaces (or suppressed)
	// Implement: for each comma position, look left at resInt digits; if no non-space digit found, space it
	for i := 0; i < len(intPic); i++ {
		if intPic[i] == ',' {
			hasDigit := false
			for j := 0; j < i; j++ {
				if resInt[j] != ' ' && resInt[j] != ',' {
					hasDigit = true
					break
				}
				if resInt[j] == ',' {
					continue
				}
			}
			// Actually if left side digits are all spaces, comma is space
			// Check if any non-space non-comma exists left
			allSpace := true
			for j := 0; j < i; j++ {
				if intPic[j] == 'Z' || intPic[j] == '9' {
					if resInt[j] != ' ' {
						allSpace = false
						break
					}
				}
			}
			if allSpace {
				resInt[i] = ' '
			}
			_ = hasDigit
		}
	}

	intFormatted := string(resInt)

	// Fractional part
	fracFormatted := ""
	if scale > 0 {
		// get fractional digits with leading zeros to scale
		// fracPart * 10^scale
		pow := decimal.NewFromInt(1)
		for i := 0; i < scale; i++ {
			pow = pow.Mul(decimal.NewFromInt(10))
		}
		fracInt := fracPart.Mul(pow).Truncate(0)
		fracStr := fracInt.StringFixed(0)
		if len(fracStr) < scale {
			fracStr = strings.Repeat("0", scale-len(fracStr)) + fracStr
		}
		if len(fracStr) > scale {
			fracStr = fracStr[len(fracStr)-scale:]
		}
		fracFormatted = "." + fracStr
	}

	result := intFormatted + fracFormatted
	if neg {
		// COBOL would show sign; not needed for this program
		result = "-" + result
	}
	return result
}

func parseDiscRec(line string) DiscRec {
	// line padded to 15
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	}
	if len(line) > 15 {
		line = line[:15]
	}
	item := line[0:6]
	priceStr := line[6:13]
	pctStr := line[13:15]

	priceStr = strings.TrimSpace(priceStr)
	var price decimal.Decimal
	if priceStr == "" {
		price = decimal.NewFromInt(0)
	} else {
		// digits only, implied 2 decimals
		// parse as integer
		// may contain spaces? already trimmed
		d, err := decimal.NewFromString(priceStr)
		if err != nil {
			d = decimal.NewFromInt(0)
		}
		price = decimal.New(d.IntPart(), -2)
		// store truncated? file read exact
		price = truncateDecimal(price, 2)
	}
	pctStr = strings.TrimSpace(pctStr)
	var pct int64
	if pctStr != "" {
		var v int64
		fmt.Sscan(pctStr, &v)
		pct = v
	}
	return DiscRec{DrItem: item, DrPrice: price, DrPct: pct}
}

func mainPara() {
	openDiscFile()
	readPara()
	for !isInputDone() {
		processPara()
	}
	closeDiscFile()
	summaryPara()
}

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func openDiscFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not exists, treat as EOF
		WsEofFlag = "Y"
		return
	}
	discFile = f
	discFileScanner = bufio.NewScanner(f)
	// allow long lines
}

func closeDiscFile() {
	if discFile != nil {
		discFile.Close()
	}
}

func readPara() {
	if discFileScanner == nil {
		WsEofFlag = "Y"
		return
	}
	if discFileScanner.Scan() {
		line := discFileScanner.Text()
		// COBOL LINE SEQUENTIAL strips trailing spaces? But we pad
		// Scanner removes newline, keeps other chars
		// Need to pad to record length
		DiscRecVar = parseDiscRec(line)
	} else {
		WsEofFlag = "Y"
	}
}

func processPara() {
	// COMPUTE WS-DISCOUNT ROUNDED = DR-PRICE * DR-PCT / 100
	pctDec := decimal.NewFromInt(DiscRecVar.DrPct)
	raw := DiscRecVar.DrPrice.Mul(pctDec).Shift(-2)
	rounded := roundDecimal(raw, 2)
	WsDiscount = storePic95V99(rounded)

	// COMPUTE WS-NET = DR-PRICE - WS-DISCOUNT
	netRaw := DiscRecVar.DrPrice.Sub(WsDiscount)
	WsNet = storePic95V99(netRaw)

	// ADD WS-NET TO WS-TOTAL-NET
	WsTotalNet = WsTotalNet.Add(WsNet)
	WsTotalNet = storePic98V99(WsTotalNet)

	WsCount++

	WsPriceEd = formatEdited(DiscRecVar.DrPrice, "ZZ,ZZ9.99")
	WsDiscEd = formatEdited(WsDiscount, "ZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZ,ZZ9.99")

	// DISPLAY DR-ITEM " " WS-PRICE-ED " " DR-PCT "% " WS-DISC-ED " " WS-NET-ED
	// DR-PCT is PIC 9(2) prints zero-padded to 2 digits
	pctDisplay := fmt.Sprintf("%02d", DiscRecVar.DrPct)
	// DR-ITEM is X(6) exactly
	fmt.Printf("%s %s %s%% %s %s\n", DiscRecVar.DrItem, WsPriceEd, pctDisplay, WsDiscEd, WsNetEd)

	readPara()
}

func summaryPara() {
	WsTotalEd = formatEdited(WsTotalNet, "ZZ,ZZZ,ZZ9.99")
	// WS-COUNT PIC 9(3) zero-padded to 3 digits when displayed? But DISPLAY numeric unedited prints as defined? In COBOL DISPLAY of PIC 9(3) prints digits. So zero-padded.
	countDisplay := fmt.Sprintf("%03d", WsCount)
	fmt.Printf("ITEMS: %s NET TOTAL: %s\n", countDisplay, WsTotalEd)
}

func main() {
	mainPara()
}

